                        Box::<dyn std::error::Error + Send + Sync>::from(e)
                    },
                )?,
                None => arguments::StatusFilter::Active,
            };
            ListCommand::execute(
                api_client,
                None,
                json,
                None,
                None,
                Some(arguments::Entity::Project {
                    json,
                    status: status_filter,
                }),
            )
            .await
        }
        ProjectAction::Create { name, color } => {
            CreateProjectCommand::execute(api_client, name, color).await
        }
        ProjectAction::Rename { old_name, new_name } => {
            RenameProjectCommand::execute(api_client, old_name, new_name).await
        }
        ProjectAction::Delete { name } => DeleteProjectCommand::execute(api_client, name).await,
        ProjectAction::Archive { name } => {
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join(",");
        let url = format!(
            "{}/workspaces/{}/time_entries/{}",
            self.base_url, workspace_id, ids
        );
        self.patch::<Value, Value>(url, &patch).await
    }

    async fn get_time_entries_filtered(
        &self,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<Vec<TimeEntry>> {
        let (network_entries, network_projects, network_tasks, network_clients) = tokio::join!(
            self.get_time_entries(since.as_deref(), until.as_deref()),
            self.get_projects(),
            self.get_tasks(),
            self.get_clients(),
        );

        let clients: HashMap<i64, crate::models::Client> = network_clients
            .unwrap_or_default()
            .into_iter()
            .map(|c| {
                (
                    c.id,
                    crate::models::Client {
                        id: c.id,
                        name: c.name,
                        workspace_id: c.wid,
                        archived: c.archived,
                    },
                )
            })
            .collect();

        let projects: HashMap<i64, Project> = network_projects
            .unwrap_or_default()
            .into_iter()
            .map(|p| {
                (
                    p.id,
                    Project {
                        id: p.id,
                        name: p.name.clone(),
                        workspace_id: p.workspace_id,
                        client: clients.get(&p.client_id.unwrap_or(-1)).cloned(),
                        is_private: p.is_private,
                        active: p.active,
                        at: p.at,
                        created_at: p.created_at,
                        color: p.color,
                        billable: p.billable,
                    },
                )
            })
            .collect();

        let tasks: HashMap<i64, Task> = network_tasks
            .unwrap_or_default()
            .into_iter()
            .filter_map(|t| {
                projects.get(&t.project_id).map(|project| {
                    (
