use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use serde::Serialize;
use std::collections::BTreeMap;

pub struct InvoiceMonthlyCommand;

#[derive(Debug, Serialize, PartialEq)]
struct InvoiceMonthlyMonth {
    month: String,
    billable_seconds: i64,
}

#[derive(Debug, Serialize, PartialEq)]
struct InvoiceMonthlyJson {
    months: Vec<InvoiceMonthlyMonth>,
    total_billable_seconds: i64,
}

/// Apply the invoice rule to one entry: only closed billable entries contribute
/// their stored duration.
fn invoice_seconds(entry: &TimeEntry) -> Option<i64> {
    if entry.billable && entry.stop.is_some() && !entry.is_running() {
        Some(entry.duration)
    } else {
        None
    }
}

fn monthly_totals(entries: &[TimeEntry]) -> BTreeMap<String, i64> {
    let mut totals = BTreeMap::new();

    for entry in entries {
        if let Some(seconds) = invoice_seconds(entry) {
            let month = entry.start.format("%Y-%m").to_string();
            *totals.entry(month).or_insert(0) += seconds;
        }
    }

    totals
}

fn total_seconds(totals: &BTreeMap<String, i64>) -> i64 {
    totals.values().sum()
}

fn json_output(totals: &BTreeMap<String, i64>) -> InvoiceMonthlyJson {
    InvoiceMonthlyJson {
        months: totals
            .iter()
            .map(|(month, billable_seconds)| InvoiceMonthlyMonth {
                month: month.clone(),
                billable_seconds: *billable_seconds,
            })
            .collect(),
        total_billable_seconds: total_seconds(totals),
    }
}

fn print_human(totals: &BTreeMap<String, i64>) {
    if totals.is_empty() {
        println!("(no data)");
        return;
    }

    for (month, seconds) in totals {
        println!("{month}  {seconds}s");
    }
    println!("Total  {}s", total_seconds(totals));
}

impl InvoiceMonthlyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
        json: bool,
    ) -> ResultWithDefaultError<()> {
        let (since_filter, until_filter) =
            utilities::normalize_time_entry_list_filters(since, until)?;
        let since = since_filter
            .as_deref()
            .map(utilities::parse_datetime_input)
            .transpose()?;
        let until = until_filter
            .as_deref()
            .map(utilities::parse_datetime_input)
            .transpose()?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since_filter, until_filter)
            .await?;
        let entries = entries
            .into_iter()
            .filter(|entry| {
                since.is_none_or(|since| entry.start >= since)
                    && until.is_none_or(|until| entry.start < until)
            })
            .collect::<Vec<_>>();
        let totals = monthly_totals(&entries);

        if json {
            println!(
                "{}",
                serde_json::to_string(&json_output(&totals))
                    .expect("failed to serialize monthly invoice")
            );
        } else {
            print_human(&totals);
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::{DateTime, Duration, Utc};

    fn entry(start: &str, duration: i64, billable: bool, running: bool) -> TimeEntry {
        let start = start.parse::<DateTime<Utc>>().unwrap();
        TimeEntry {
            id: 1,
            description: String::new(),
            start,
            stop: (!running).then_some(start + Duration::seconds(duration)),
            duration: if running {
                -start.timestamp()
            } else {
                duration
            },
            billable,
            workspace_id: 1,
            tags: Vec::new(),
            project: None,
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn invoice_rule_uses_only_closed_billable_entries() {
        let entries = vec![
            entry("2026-02-01T00:00:00Z", 1800, true, false),
            entry("2026-02-01T01:00:00Z", 900, false, false),
            entry("2026-02-01T02:00:00Z", 600, true, true),
        ];

        assert_eq!(
            monthly_totals(&entries).into_iter().collect::<Vec<_>>(),
            [("2026-02".to_string(), 1800),]
        );
    }

    #[test]
    fn monthly_totals_are_utc_and_oldest_first() {
        let entries = vec![
            entry("2026-02-01T00:00:00Z", 1200, true, false),
            entry("2025-12-31T23:59:59Z", 600, true, false),
            entry("2026-01-15T00:00:00Z", 900, true, false),
        ];
        let totals = monthly_totals(&entries);

        assert_eq!(
            totals.into_iter().collect::<Vec<_>>(),
            vec![
                ("2025-12".to_string(), 600),
                ("2026-01".to_string(), 900),
                ("2026-02".to_string(), 1200),
            ]
        );
    }

    #[test]
    fn json_output_has_requested_shape_and_empty_values() {
        let totals = BTreeMap::from([("2026-01".to_string(), 1800), ("2026-02".to_string(), 2700)]);
        let output = serde_json::to_value(json_output(&totals)).unwrap();

        assert_eq!(
            output,
            serde_json::json!({
                "months": [
                    {"month": "2026-01", "billable_seconds": 1800},
                    {"month": "2026-02", "billable_seconds": 2700}
                ],
                "total_billable_seconds": 4500
            })
        );

        assert_eq!(
            serde_json::to_value(json_output(&BTreeMap::new())).unwrap(),
            serde_json::json!({"months": [], "total_billable_seconds": 0})
        );
    }
}

