+    use chrono::{DateTime, Duration, Utc};
+
+    fn entry(start: &str, duration: i64, billable: bool, running: bool) -> TimeEntry {
+        let start = start.parse::<DateTime<Utc>>().unwrap();
+        TimeEntry {
+            id: 1,
+            description: String::new(),
+            start,
+            stop: (!running).then_some(start + Duration::seconds(duration)),
+            duration: if running {
+                -start.timestamp()
+            } else {
+                duration
+            },
+            billable,
+            workspace_id: 1,
+            tags: Vec::new(),
+            project: None,
+            task: None,
+            created_with: None,
+        }
+    }
+
+    #[test]
+    fn invoice_rule_uses_only_closed_billable_entries() {
+        let entries = vec![
+            entry("2026-02-01T00:00:00Z", 1800, true, false),
+            entry("2026-02-01T01:00:00Z", 900, false, false),
+            entry("2026-02-01T02:00:00Z", 600, true, true),
+        ];
+
+        assert_eq!(
+            monthly_totals(&entries).into_iter().collect::<Vec<_>>(),
+            [("2026-02".to_string(), 1800),]
+        );
+    }
+
+    #[test]
+    fn monthly_totals_are_utc_and_oldest_first() {
+        let entries = vec![
+            entry("2026-02-01T00:00:00Z", 1200, true, false),
+            entry("2025-12-31T23:59:59Z", 600, true, false),
+            entry("2026-01-15T00:00:00Z", 900, true, false),
+        ];
+        let totals = monthly_totals(&entries);
+
+        assert_eq!(
+            totals.into_iter().collect::<Vec<_>>(),
+            vec![
+                ("2025-12".to_string(), 600),
+                ("2026-01".to_string(), 900),
+                ("2026-02".to_string(), 1200),
+            ]
+        );
+    }
+
+    #[test]
+    fn json_output_has_requested_shape_and_empty_values() {
+        let totals = BTreeMap::from([("2026-01".to_string(), 1800), ("2026-02".to_string(), 2700)]);
+        let output = serde_json::to_value(json_output(&totals)).unwrap();
+
+        assert_eq!(
+            output,
+            serde_json::json!({
+                "months": [
+                    {"month": "2026-01", "billable_seconds": 1800},
+                    {"month": "2026-02", "billable_seconds": 2700}
+                ],
+                "total_billable_seconds": 4500
+            })
+        );
+
+        assert_eq!(
+            serde_json::to_value(json_output(&BTreeMap::new())).unwrap(),
+            serde_json::json!({"months": [], "total_billable_seconds": 0})
+        );
+    }
