  9	
 10	#[derive(Debug, Serialize, PartialEq)]
 11	struct InvoiceMonthlyMonth {
 12	    month: String,
 13	    billable_seconds: i64,
 14	}
 15	
 16	#[derive(Debug, Serialize, PartialEq)]
 17	struct InvoiceMonthlyJson {
 18	    months: Vec<InvoiceMonthlyMonth>,
 19	    total_billable_seconds: i64,
 20	}
 21	
 22	/// Apply the invoice rule to one entry: only closed billable entries contribute
 23	/// their stored duration.
 24	fn invoice_seconds(entry: &TimeEntry) -> Option<i64> {
 25	    if entry.billable && entry.stop.is_some() && !entry.is_running() {
 26	        Some(entry.duration)
 27	    } else {
 28	        None
 29	    }
 30	}
 31	
 32	fn monthly_totals(entries: &[TimeEntry]) -> BTreeMap<String, i64> {
 33	    let mut totals = BTreeMap::new();
 34	
 35	    for entry in entries {
 36	        if let Some(seconds) = invoice_seconds(entry) {
 37	            let month = entry.start.format("%Y-%m").to_string();
 38	            *totals.entry(month).or_insert(0) += seconds;
 39	        }
 40	    }
 41	
 42	    totals
 43	}
 44	
 45	fn total_seconds(totals: &BTreeMap<String, i64>) -> i64 {
 46	    totals.values().sum()
 47	}
 48	
 49	fn is_in_window(
 50	    entry: &TimeEntry,
 51	    since: Option<DateTime<Utc>>,
 52	    until: Option<DateTime<Utc>>,
 53	) -> bool {
 54	    since.is_none_or(|since| entry.start >= since) && until.is_none_or(|until| entry.start < until)
 55	}
 56	
 57	fn json_output(totals: &BTreeMap<String, i64>) -> InvoiceMonthlyJson {
 58	    InvoiceMonthlyJson {
 59	        months: totals
 60	            .iter()
 61	            .map(|(month, billable_seconds)| InvoiceMonthlyMonth {
 62	                month: month.clone(),
 63	                billable_seconds: *billable_seconds,
 64	            })
 65	            .collect(),
 66	        total_billable_seconds: total_seconds(totals),
 67	    }
 68	}
 69	
 70	fn print_human(totals: &BTreeMap<String, i64>) {
 71	    if totals.is_empty() {
 72	        println!("(no data)");
 73	        return;
 74	    }
 75	
 76	    for (month, seconds) in totals {
 77	        println!("{month}  {seconds}s");
 78	    }
 79	    println!("Total  {}s", total_seconds(totals));
 80	}
