 82	impl InvoiceMonthlyCommand {
 83	    pub async fn execute(
 84	        api_client: impl ApiClient,
 85	        since: Option<String>,
 86	        until: Option<String>,
 87	        json: bool,
 88	    ) -> ResultWithDefaultError<()> {
 89	        let (since_filter, until_filter) =
 90	            utilities::normalize_time_entry_list_filters(since, until)?;
 91	        let since = since_filter
 92	            .as_deref()
 93	            .map(utilities::parse_datetime_input)
 94	            .transpose()?;
 95	        let until = until_filter
 96	            .as_deref()
 97	            .map(utilities::parse_datetime_input)
 98	            .transpose()?;
 99	        let entries = api_client
100	            .get_time_entries_filtered_minimal(since_filter, until_filter)
101	            .await?;
102	        let entries = entries
103	            .into_iter()
104	            .filter(|entry| is_in_window(entry, since, until))
105	            .collect::<Vec<_>>();
106	        let totals = monthly_totals(&entries);
107	
108	        if json {
109	            println!(
110	                "{}",
111	                serde_json::to_string(&json_output(&totals))
112	                    .expect("failed to serialize monthly invoice")
113	            );
114	        } else {
115	            print_human(&totals);
116	        }
117	
118	        Ok(())
119	    }
120	}
